            InstantiationUtil.deserializeObject(
                    tokens, AbstractS3DelegationTokenReceiver.class.getClassLoader());
    String accessToken = credentials.getSessionToken();
    LOG.info("Session credential: {}", accessToken);
    LOG.info("Session credential refresh complete");
